  `title` varchar(200) NOT NULL,
  `description` longtext,
  `type` varchar(20) NOT NULL,
  `priority` varchar(20) NOT NULL,
  `date` date NOT NULL,
  `time` time(6) NOT NULL,
  `duration` int unsigned NOT NULL,
  `location` varchar(300) DEFAULT NULL,
