DROP TABLE IF EXISTS `dashboard_malzemehareketi`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dashboard_malzemehareketi` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tarih` date NOT NULL,
  `faturano` varchar(100) NOT NULL,
  `musteri` varchar(255) NOT NULL,
  `urun` varchar(255) NOT NULL,
  `tutar` decimal(14,2) NOT NULL,
  `odeme_sekli` varchar(100) NOT NULL,
  `eklenme_zamani` datetime(6) NOT NULL,
  `kullanici_id` int DEFAULT NULL,
  `dosya_id` bigint DEFAULT NULL,
  `kategori` varchar(255) DEFAULT NULL,
  `ref` varchar(100) DEFAULT NULL,
  `marka` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `dashboard_malzemehareketi_kullanici_id_13b8cf88_fk_auth_user_id` (`kullanici_id`),
  KEY `dashboard_malzemehar_dosya_id_7c1f906d_fk_dashboard` (`dosya_id`),
  CONSTRAINT `dashboard_malzemehar_dosya_id_7c1f906d_fk_dashboard` FOREIGN KEY (`dosya_id`) REFERENCES `dashboard_malzemedosya` (`id`),
  CONSTRAINT `dashboard_malzemehareketi_kullanici_id_13b8cf88_fk_auth_user_id` FOREIGN KEY (`kullanici_id`) REFERENCES `auth_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=734 DEFAULT CHARSET=utf8mb3;
