--
-- Table structure for table `dashboard_notification`
--

DROP TABLE IF EXISTS `dashboard_notification`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dashboard_notification` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL,
  `message` longtext NOT NULL,
  `type` varchar(20) NOT NULL,
  `status` varchar(20) NOT NULL,
  `scheduled_time` datetime(6) NOT NULL,
  `sent_time` datetime(6) DEFAULT NULL,
  `read_time` datetime(6) DEFAULT NULL,
  `extra_data` longtext,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `user_id` int NOT NULL,
  `snooze_count` int NOT NULL,
  `snoozed_until` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `dashboard_notification_user_id_e4f6848c_fk_auth_user_id` (`user_id`),
