--
-- Table structure for table `dashboard_transaction`
--

DROP TABLE IF EXISTS `dashboard_transaction`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dashboard_transaction` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `hareket_tipi` varchar(10) NOT NULL,
  `tarih` date NOT NULL,
  `kasa_adi` varchar(20) NOT NULL,
  `nakit` decimal(12,2) NOT NULL,
  `kredi_karti` decimal(12,2) NOT NULL,
  `cari` decimal(12,2) NOT NULL,
  `aciklama` varchar(255) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `created_by_id` int DEFAULT NULL,
  `kategori1_id` bigint DEFAULT NULL,
  `kategori2_id` bigint DEFAULT NULL,
  `kategori3_id` bigint DEFAULT NULL,
  `mehmet_havale` decimal(12,2) NOT NULL,
  `sanal_pos` decimal(12,2) NOT NULL,
  `banka_havale` decimal(12,2) NOT NULL,
  `pafgo` decimal(12,2) NOT NULL,
  `canta_cikis` decimal(12,2) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `dashboard_transaction_created_by_id_9a14515a_fk_auth_user_id` (`created_by_id`),
  KEY `dashboard_transactio_kategori1_id_66c4e7a5_fk_dashboard` (`kategori1_id`),
  KEY `dashboard_transactio_kategori2_id_8bfda5c3_fk_dashboard` (`kategori2_id`),
  KEY `dashboard_transactio_kategori3_id_ee2e36ac_fk_dashboard` (`kategori3_id`),
  CONSTRAINT `dashboard_transactio_kategori1_id_66c4e7a5_fk_dashboard` FOREIGN KEY (`kategori1_id`) REFERENCES `dashboard_transactioncategory` (`id`),
  CONSTRAINT `dashboard_transactio_kategori2_id_8bfda5c3_fk_dashboard` FOREIGN KEY (`kategori2_id`) REFERENCES `dashboard_transactioncategory` (`id`),
  CONSTRAINT `dashboard_transactio_kategori3_id_ee2e36ac_fk_dashboard` FOREIGN KEY (`kategori3_id`) REFERENCES `dashboard_transactioncategory` (`id`),
  CONSTRAINT `dashboard_transaction_created_by_id_9a14515a_fk_auth_user_id` FOREIGN KEY (`created_by_id`) REFERENCES `auth_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1226 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

